using Dapper;
using SmartSchool.Application.Persistence;
namespace SmartSchool.Api.Features;
public static class ActorProfileEndpoints
{
 public static IEndpointRouteBuilder MapActorProfileEndpoints(this IEndpointRouteBuilder e){var g=e.MapGroup("/api/profiles").RequireAuthorization().WithTags("Profiles");g.MapGet("/students/{id:guid}",(Guid id,Guid tenantId,IDbConnectionFactory f,CancellationToken ct)=>Get("SELECT student_id AS \"Id\",tenant_id AS \"TenantId\",user_id AS \"UserId\",student_number AS \"StudentNumber\",first_name AS \"FirstName\",last_name AS \"LastName\",date_of_birth AS \"DateOfBirth\",gender AS \"Gender\",admission_date AS \"AdmissionDate\",status AS \"Status\" FROM student.student WHERE tenant_id=@TenantId AND student_id=@Id",id,tenantId,f,ct));g.MapGet("/parents/{id:guid}",(Guid id,Guid tenantId,IDbConnectionFactory f,CancellationToken ct)=>Get("SELECT guardian_id AS \"Id\",tenant_id AS \"TenantId\",user_id AS \"UserId\",full_name AS \"FullName\",cnic_number AS \"CnicNumber\",email AS \"Email\",phone AS \"Phone\" FROM student.guardian WHERE tenant_id=@TenantId AND guardian_id=@Id",id,tenantId,f,ct));g.MapGet("/teachers/{id:guid}",(Guid id,Guid tenantId,IDbConnectionFactory f,CancellationToken ct)=>Get("SELECT employee_id AS \"Id\",tenant_id AS \"TenantId\",user_id AS \"UserId\",employee_number AS \"EmployeeNumber\",first_name AS \"FirstName\",last_name AS \"LastName\",cnic_number AS \"CnicNumber\",email AS \"Email\",phone AS \"Phone\",hire_date AS \"HireDate\",employment_type_code AS \"EmploymentTypeCode\",status AS \"Status\" FROM hr.employee WHERE tenant_id=@TenantId AND employee_id=@Id",id,tenantId,f,ct));g.MapGet("/drivers/{id:guid}",(Guid id,Guid tenantId,IDbConnectionFactory f,CancellationToken ct)=>Get("SELECT driver_id AS \"Id\",tenant_id AS \"TenantId\",employee_id AS \"EmployeeId\",driver_number AS \"DriverNumber\",full_name AS \"FullName\",cnic_number AS \"CnicNumber\",phone AS \"Phone\",driving_license_number AS \"DrivingLicenseNumber\",driving_license_category AS \"DrivingLicenseCategory\",driving_license_expires_on AS \"DrivingLicenseExpiresOn\",status AS \"Status\",is_active AS \"IsActive\",created_at AS \"CreatedAt\",updated_at AS \"UpdatedAt\" FROM transport.driver WHERE tenant_id=@TenantId AND driver_id=@Id",id,tenantId,f,ct));return e;}
 private static async Task<IResult> Get(string q,Guid id,Guid tenantId,IDbConnectionFactory f,CancellationToken ct){await using var c=await f.OpenConnectionAsync(ct);var row=await c.QuerySingleOrDefaultAsync(new CommandDefinition(q,new{Id=id,TenantId=tenantId},cancellationToken:ct));return row is null?Results.NotFound():Results.Ok(row);}
}
